mapper.select:
SELECT COM.COMPONENT_TYPE , COM.COMPONENT_NAME , COM.COMPONENT_COMMENT , COM.CHANGE_TYPE , CHA.CHANGE_COLUMN , CHA.BEFORE_VALUE , CHA.AFTER_VALUE FROM DBF_COMMIT_COMPONENT COM INNER JOIN DBF_COMMIT_CHANGE CHA ON COM.COMMIT_COMPONENT_ID = CHA.COMMIT_COMPONENT_ID WHERE COM.COMMIT_TARGET_ID = #{commitTargetId}
AND COM.COMPONENT_NAME = #{componentName}
ORDER BY CASE COM.CHANGE_TYPE WHEN 'ADD' THEN 1 WHEN 'MOD' THEN 2 WHEN 'DEL' THEN 3 ELSE 99 END , COM.COMMIT_COMPONENT_ID
